function syncLyrics(force=false){if(!lyricRows.length)return;const now=audio.currentTime-(state.offsets[SONGS[songIndex].id]||0);let idx=-1;for(let i=0;i<lyricRows.length;i++){if(lyricRows[i].t<=now)idx=i;else break}if(idx===lyricIndex&&!force)return;lyricIndex=idx;$$('.lyric-line').forEach((b,i)=>b.classList.toggle('current',i===idx||(idx>=0&&lyricRows[i].t===lyricRows[idx].t)));if(idx>=0&&page==='music'&&(force||Date.now()-lastManualScroll>4500)){const el=$(`[data-line="${idx}"]`);programmaticScroll=true;$('#lyrics').scrollTo({top:el.getBoundingClientRect().top-$('#lyrics').getBoundingClientRect().top+$('#lyrics').scrollTop-$('#lyrics').clientHeight/2+el.clientHeight/2,behavior:state.reduced?'instant':'smooth'});setTimeout(()=>programmaticScroll=false,800)}}$('#lyrics').addEventListener('wheel',()=>lastManualScroll=Date.now(),{passive:true});$('#lyrics').addEventListener('touchstart',()=>lastManualScroll=Date.now(),{passive:true});$('#lrcFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1024*1024)return toast('歌词文件过大，请选择 1 MB 以下的 LRC。');const text=await f.text();if(!parseLRC(text).length)return toast('没有找到时间标签，请使用含 [00:12.34] 格式的 LRC。');state.lyrics[SONGS[songIndex].id]=text;persist();renderLyrics();toast('歌词已保存，可以点击任意一句跳转。');e.target.value=''};$('#offset').onchange=()=>{const n=Math.max(-60,Math.min(60,Number($('#offset').value)||0));state.offsets[SONGS[songIndex].id]=n;$('#offset').value=n;persist();syncLyrics(true)};
$('#musicFile').onchange=e=>{const files=[...e.target.files].filter(f=>!f.type||f.type.startsWith('audio/'));if(!files.length)return;const start=SONGS.length;files.forEach((f,i)=>SONGS.push({id:'local-'+Date.now()+'-'+i,title:f.name.replace(/\.[^.]+$/,''),zh:'本地歌曲',src:URL.createObjectURL(f),cover:'assets/albums/結束バンド.jpg',duration:0,local:true}));setTrack(start,true);toast(`已加入 ${files.length} 首歌曲，本次打开期间可播放。`)};
function renderVideos(){const groups=[['live','动画现场','从 STARRY 到秀华祭，重温真正的演奏画面。'],['mv','完整 MV · OP / ED','听完整首歌，也把字幕和弹幕一起打开。'],['local','我的放映','本次打开期间导入的视频。']];$('#videoGrid').innerHTML=groups.map(([key,title,desc])=>{const rows=VIDEOS.map((v,i)=>({v,i})).filter(({v})=>(v.src?'local':v.kind.startsWith('动画演奏')?'live':'mv')===key);if(!rows.length)return '';return `<section class="video-category" id="videos-${key}"><div class="video-category-head"><span>${key==='live'?'01':key==='mv'?'02':'03'}</span><div><h2>${title}</h2><p>${desc}</p></div><small>${rows.length} 部</small></div><div class="video-category-grid">${rows.map(({v,i})=>`<button class="video-card" data-video="${i}"><img src="${v.cover}" alt="${escapeHTML(v.title)}" loading="lazy"><div><small>${escapeHTML(v.kind)}</small><h3>▷ ${escapeHTML(v.title)}</h3><p>${v.src?'本地直接播放':(v.views/10000).toFixed(1)+' 万播放 · 哔哩哔哩'}</p></div></button>`).join('')}</div></section>`}).join('');$$('[data-video]').forEach(b=>b.onclick=()=>loadVideo(+b.dataset.video))}
function loadVideo(i){stopVideo();audio.pause();const v=VIDEOS[i];$('#screen').replaceChildren();if(v.src){const video=document.createElement('video');video.controls=true;video.playsInline=true;video.preload='metadata';video.src=v.src;video.poster=v.cover;video.volume=state.volume;video.addEventListener('play',()=>audio.pause());$('#screen').append(video);video.play().catch(()=>toast('轻触播放开始观看。'))}else{const frame=document.createElement('iframe');frame.src='https://player.bilibili.com/player.html?bvid='+v.bvid+'&cid='+v.cid+'&page=1&autoplay=0&danmaku=1';frame.title=v.title+' · 哔哩哔哩播放器';frame.allow='autoplay; fullscreen; picture-in-picture';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';$('#screen').append(frame)}$('#videoTitle').textContent=v.title;$('#videoNote').textContent=v.note;$('#bilibiliLink').hidden=!v.bvid;if(v.bvid)$('#bilibiliLink').href='https://www.bilibili.com/video/'+v.bvid;$('#screen').scrollIntoView({behavior:state.reduced?'instant':'smooth',block:'center'})}
$('#showLive').onclick=()=>{navigate('cinema');const map={1:0,2:1,3:2,4:3};if(map[songIndex]!==undefined)loadVideo(map[songIndex]);else toast('请选择下方的 B 站演奏片段。')};
$('#theaterMode').onclick=()=>{document.body.classList.toggle('cinema-dark');$('#theaterMode').textContent=document.body.classList.contains('cinema-dark')?'◑ 开灯':'◐ 关灯观看'};$('#videoFile').onchange=e=>{const f=e.target.files[0];if(!f)return;videoUrl=URL.createObjectURL(f);VIDEOS.push({title:f.name,kind:'LOCAL',note:'本地导入，仅在本机播放；刷新后需重新选择。',src:videoUrl,cover:'assets/art/b-ep08.jpg'});renderVideos();loadVideo(VIDEOS.length-1)};
$('#settingsButton').onclick=()=>{showModal('把这里调成你喜欢的样子',`<div class="setting-row"><label for="textSpeed">对话文字</label><select id="textSpeed"><option value="0">立即显示</option><option value="24">舒适速度</option><option value="45">慢慢出现</option></select></div><div class="setting-row"><label for="reduceMotion">减少动画</label><input id="reduceMotion" type="checkbox" ${state.reduced?'checked':''}></div><div class="setting-row"><span>存档</span><button class="ghost" id="exportSave">导出存档</button><label class="ghost">导入存档<input type="file" id="importSave" accept=".json" hidden></label></div><div class="setting-row"><span>播放顺序</span><button class="ghost" id="settingsMode">${['列表循环','单曲循环','随机播放'][state.mode]}</button></div><p style="margin-top:20px">非官方个人同人作品。对话与剧情为原创，主美术优先采用官方角色立绘与剧照。媒体素材来源及参考仓库见 <a href="CREDITS.md" target="_blank" style="color:var(--pink)">素材说明 ↗</a>。<br>进度仅保存在当前浏览器；无登录、无付费、无打卡要求。</p>`);$('#textSpeed').value=state.speed;$('#textSpeed').onchange=()=>{state.speed=+$('#textSpeed').value;persist()};$('#reduceMotion').onchange=()=>{state.reduced=$('#reduceMotion').checked;document.body.classList.toggle('reduced-motion',state.reduced);persist();if(state.reduced)cancelAnimationFrame(spectrumRAF);else if(!audio.paused)startSpectrum()};$('#settingsMode').onclick=()=>{state.mode=(state.mode+1)%3;updateMode();persist();$('#settingsMode').textContent=['列表循环','单曲循环','随机播放'][state.mode]};$('#exportSave').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='STARRY-回忆存档.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#importSave').onchange=async e=>{try{const f=e.target.files[0];if(!f||f.size>2e6)throw Error();const data=JSON.parse(await f.text());if(data.version!==2||!Array.isArray(data.completed)||data.completed.length!==4||!data.completed.every(n=>Number.isInteger(n)&&n>=0&&n<=3))throw Error();state.completed=data.completed;state.picks=data.picks&&typeof data.picks==='object'?data.picks:{};state.favorites=Array.isArray(data.favorites)?data.favorites.filter(x=>typeof x==='string'):[];if(validGacha(data.gacha))state.gacha=data.gacha;state.lyrics=data.lyrics&&typeof data.lyrics==='object'?Object.fromEntries(Object.entries(data.lyrics).filter(([k,v])=>typeof v==='string'&&v.length<1e6)):{};state.offsets=data.offsets&&typeof data.offsets==='object'?Object.fromEntries(Object.entries(data.offsets).filter(([k,v])=>Number.isFinite(v)&&Math.abs(v)<=60)):{};state.session=null;persist();renderGacha();$('#modal').close();navigate('memories');updateFav();renderPlaylist();toast('存档读取成功。下北泽行动继续。')}catch{toast('这不是有效的 STARRY 存档，现有进度没有改变。')}}};
renderCast();renderRoutes();renderVideos();setTrack(songIndex);updateMode();
